choose.when:
AND (r.current_stage = 'formatReview'
     OR r.created_by = #{scopeUserId}
     OR EXISTS (SELECT 1 FROM aup_audit_log l WHERE l.aup_id = r.id AND l.actor = #{scopeUserId}))

AND (r.created_by = #{scopeUserId}
     OR EXISTS (SELECT 1 FROM aup_review_assignment a
            WHERE a.aup_id = r.id AND a.reviewer_id = #{scopeUserId}))

where.if:
AND (r.created_by = #{scopeUserId}
     OR r.pi_user_id = #{scopeUserId}
     OR EXISTS (SELECT 1 FROM aup_review_assignment a WHERE a.aup_id = r.id AND a.reviewer_id = #{scopeUserId})
     OR EXISTS (SELECT 1 FROM aup_audit_log l WHERE l.aup_id = r.id AND l.actor = #{scopeUserId}))

AND (
  EXISTS (SELECT 1 FROM aup_review_assignment a WHERE a.aup_id = r.id AND (
    a.reviewer_id IN (SELECT user_id FROM aro_personnel WHERE name LIKE CONCAT('%', #{reviewerName}, '%'))
    OR a.reviewer_id IN (SELECT id FROM sys_user WHERE display_nickname LIKE CONCAT('%', #{reviewerName}, '%') OR username LIKE CONCAT('%', #{reviewerName}, '%'))
  ))
  OR EXISTS (SELECT 1 FROM aup_audit_log l WHERE l.aup_id = r.id AND (
    l.actor IN (SELECT user_id FROM aro_personnel WHERE name LIKE CONCAT('%', #{reviewerName}, '%'))
    OR l.actor IN (SELECT id FROM sys_user WHERE display_nickname LIKE CONCAT('%', #{reviewerName}, '%') OR username LIKE CONCAT('%', #{reviewerName}, '%'))
  ))
)

mapper.select:
SELECT id FROM aup_record
WHERE template_id = #{templateId}
  AND (COALESCE(is_demo, 0) = 1 OR COALESCE(created_by, '') IN ('aro', 'demo'))

SELECT CAST(id AS CHAR) AS id, register_no AS registerNo, project_group_name AS projectGroupName, project_group_id AS projectGroupId FROM aup_record WHERE current_stage = 'approved'
AND project_group_name = #{projectGroupName}
ORDER BY id ASC
